    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key, value = self._items.popitem(last=False)
        return (key, value)
    except KeyError:
        raise KeyError("popitem(): dictionary is empty")

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    if key in self:
        return self[key]
    else:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, method)
    return decorator

def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    """
    Write to the specified filename, the provided binary buffer
    Create the file if required.
    :param file_name:  File name.
    :type file_name: str
    :param text_buffer: Text buffer to write.
    :type text_buffer: str
    :param encoding: The encoding to use.
    :type encoding: str
    :param overwrite: If true, file is overwritten.
    :type overwrite: bool
    :return: The number of bytes written or lt 0 if error.
    :rtype int
    """

    if not isinstance(text_buffer, str):
        raise ValueError("text_buffer must be a string")

    if not isinstance(encoding, str):
        raise ValueError("encoding must be a string")

    if not isinstance(overwrite, bool):
        raise ValueError("overwrite must be a boolean")

    if not os.path.exists(file_name):
        with open(file_name, "w", encoding=encoding) as f:
            f.write(text_buffer)
            return len(text_buffer)
    else:
        if overwrite:
            with open(file_name, "w", encoding=encoding) as f:
                f.write(text_buffer)
                return len(text_buffer)
        else:
            with open(file_name, "a", encoding=encoding) as f:
                f.write(text_buffer)
                return len(text_buffer)

def directlyProvidedBy(object):
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    return object.__providedBy__()

def patched_normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            patched_normalizeargs(v, output)

    return output

def is_fill_request_seq(seq):
    """
    Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if isinstance(seq, FillRequest):
        return True
    elif isinstance(seq, list):
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    return False

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return {k: v for k, v in d1.items() if k not in d2 or v != d2[k]}
    else:
        result = {}
        for k, v in d1.items():
            if k not in d2 or v != d2[k]:
                result[k] = v
            elif isinstance(v, dict):
                sub_result = difference(v, d2[k], level - 1)
                if sub_result:
                    result[k] = sub_result
        return result

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not path:
        raise ValueError("path cannot be empty")

    if not os.path.exists(path):
        raise ValueError("path does not exist")

    if not os.path.isdir(path):
        raise ValueError("path is not a directory")

    # Check for required files and directories
    required_files = ["ocfl_root.json", "inventory.json"]
    required_dirs = ["content", "version"]

    for file in required_files:
        if not os.path.exists(os.path.join(path, file)):
            raise ValueError(f"Required file {file} does not exist")

    for dir in required_dirs:
        if not os.path.exists(os.path.join(path, dir)):
            raise ValueError(f"Required directory {dir} does not exist")

    # Check for valid JSON files
    for file in required_files:
        with open(os.path.join(path, file), "r") as f:
            try:
                json.load(f)
            except json.JSONDecodeError:
                raise ValueError(f"{file} is not valid JSON")

    # Check for valid inventory
    inventory_path = os.path.join(path, "inventory.json")
    with open(inventory_path, "r") as f:
        inventory = json.load(f)

    if "version" not in inventory:
        raise ValueError("Inventory does not have a version")

    if "digital_object_id" not in inventory:
        raise ValueError("Inventory does not have a digital_object_id")

    if "head" not in inventory:
        raise ValueError("Inventory does not have a head")

    if "versions" not in inventory:
        raise ValueError("Inventory does not have any versions")

    if not isinstance(inventory["version"], str):
        raise ValueError("Inventory version is not a string")

    if not isinstance(inventory["digital_object_id"], str):
        raise ValueError("Inventory digital_object_id is not a string")

    if not isinstance(inventory["head"], str):
        raise ValueError("Inventory head is not a string")

    if not isinstance(inventory["versions"], list):
        raise ValueError("Inventory versions is not a list")

    for version in inventory["versions"]:
        if not isinstance(version, str):
            raise ValueError("Inventory version is not a string")

    # Check for valid content
    content_path = os.path.join(path, "content")
    for file in os.listdir(content_path):
        file_path = os.path.join(content_path, file)
        if not os.path.isfile(file_path):
            raise ValueError(f"Content file {file} is not a file")

    # Check for valid version directories
    version_path = os.path.join(path, "version")
    for dir in os.listdir(version_path):
        dir_path = os.path.join(version_path, dir)
        if not os.path.isdir(dir_path):
            raise ValueError(f"Version directory {dir} is not a directory")

        # Check for valid version files
        for file in os.listdir(dir_path):
            file_path = os.path.join(dir_path, file)
            if not os.path.isfile(file_path):
                raise ValueError(f"Version file {file} is not a file")

    return True

