def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for content_file in inventory.get_content_files(version):
        logical_path = content_file.get_logical_path()
        if logical_path in logical_path_map:
            logical_path_map[logical_path].add(content_file)
        else:
            logical_path_map[logical_path] = {content_file}
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check that the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block is not a dictionary")

    # Check that the fixity block has the correct keys
    expected_keys = {"files", "checksums"}
    if not expected_keys.issubset(fixity.keys()):
        raise ValueError("Fixity block is missing one or more required keys")

    # Check that the files list is a list of strings
    if not isinstance(fixity["files"], list):
        raise ValueError("Files list in fixity block is not a list of strings")

    # Check that each file in the files list is a string
    for file in fixity["files"]:
        if not isinstance(file, str):
            raise ValueError("File in files list is not a string")

    # Check that the checksums list is a list of dictionaries
    if not isinstance(fixity["checksums"], list):
        raise ValueError("Checksums list in fixity block is not a list of dictionaries")

    # Check that each checksum in the checksums list is a dictionary
    for checksum in fixity["checksums"]:
        if not isinstance(checksum, dict):
            raise ValueError("Checksum in checksums list is not a dictionary")

    # Check that each checksum dictionary has the correct keys
    expected_keys = {"file", "algorithm", "checksum"}
    for checksum in fixity["checksums"]:
        if not expected_keys.issubset(checksum.keys()):
            raise ValueError("Checksum dictionary is missing one or more required keys")

    # Check that each file in the files list is in the manifest files
    for file in fixity["files"]:
        if file not in manifest_files:
            raise ValueError("File in fixity block is not in the manifest files")

    # Check that each checksum in the checksums list is a valid checksum
    for checksum in fixity["checksums"]:
        algorithm = checksum["algorithm"]
        checksum = checksum["checksum"]
        if not isinstance(algorithm, str):
            raise ValueError("Checksum algorithm is not a string")
        if not isinstance(checksum, str):
            raise ValueError("Checksum is not a string")
        if algorithm not in ("md5", "sha1", "sha256"):
            raise ValueError("Checksum algorithm is not valid")
        if not re.match(r"^[a-fA-F0-9]{32}$", checksum):
            raise ValueError("Checksum is not a valid checksum")

    # Check that the fixity block is internally consistent
    if not signatures.verify(fixity):
        raise ValueError("Fixity block is not internally consistent")

