def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if debug:
        print(f"Pretty printing {self}")
    if isinstance(self, str):
        return self
    elif isinstance(self, list):
        return "[" + ", ".join(self) + "]"
    elif isinstance(self, dict):
        return "{" + ", ".join(f"{k}: {v}" for k, v in self.items()) + "}"
    else:
        return str(self)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, str):
            if arg.startswith("~"):
                new_args.append("~" + arg[1:])
            else:
                new_args.append(arg)
        elif isinstance(arg, list):
            new_args.append(self.absorb(arg))
        else:
            raise ValueError("Invalid argument type")
    return new_args

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if PY3:
        return namefunc
    else:
        return namefunc.encode()

def get_versions():
    """Get version information or return default if unable to do so."""
    versions = {}
    for module in MODULES:
        try:
            version = get_version(module)
            if version is not None:
                versions[module] = version
        except ImportError:
            versions[module] = "unknown"
    return versions

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if style == "flat":
        return ".".join(pieces)
    elif style == "semantic":
        return "-".join(pieces)
    else:
        raise ValueError("Invalid style: {0}".format(style))

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if '+' not in pieces:
        return '+'
    else:
        return '.'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: the command(s) to run
    :type commands: list
    :param args: the arguments to pass to the command(s)
    :type args: list
    :param cwd: the working directory to run the command(s) in
    :type cwd: str
    :param verbose: whether to print the output of the command(s)
    :type verbose: bool
    :param hide_stderr: whether to hide the error output of the command(s)
    :type hide_stderr: bool
    :param env: the environment variables to set for the command(s)
    :type env: dict
    """
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]
    if not isinstance(cwd, str):
        cwd = None
    if not isinstance(verbose, bool):
        verbose = False
    if not isinstance(hide_stderr, bool):
        hide_stderr = False
    if not isinstance(env, dict):
        env = None

    for command in commands:
        if not isinstance(command, str):
            raise ValueError("commands must be a list of strings")

    for arg in args:
        if not isinstance(arg, str):
            raise ValueError("args must be a list of strings")

    if cwd and not isinstance(cwd, str):
        raise ValueError("cwd must be a string")

    if not isinstance(verbose, bool):
        raise ValueError("verbose must be a boolean")

    if not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr must be a boolean")

    if env and not isinstance(env, dict):
        raise ValueError("env must be a dictionary")

    try:
        output = subprocess.check_output(commands, args, cwd, verbose, hide_stderr, env)
    except subprocess.CalledProcessError:
        msg = "couldn't run command\n{}".format(commands)
        raise ProgramError(msg)

    return output

def register_vcs_handler(vcs, method):
    """Decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Iterate through all objects in the hierarchy
    for obj in self.get_objects():
        num_objects += 1

        # Check if the object is valid
        if validate_objects:
            if self.is_valid_object(obj):
                good_objects += 1
            else:
                if show_warnings:
                    print(f"Object {obj} is not valid")

        # Check if the object's digest is valid
        if check_digests:
            if self.is_valid_digest(obj):
                good_objects += 1
            else:
                if show_warnings:
                    print(f"Object {obj} has an invalid digest")

    return num_objects, good_objects

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    result = []
    for key, value in nodes:
        if not result:
            result.append((key, value))
        else:
            for i, (existing_key, existing_value) in enumerate(result):
                if existing_key == key:
                    if isinstance(existing_value, ruamel.yaml.nodes.MappingNode):
                        if isinstance(value, ruamel.yaml.nodes.MappingNode):
                            result[i] = (key, ruamel.yaml.comments.merge_node_dicts(existing_value.value, value.value))
                        else:
                            result[i] = (key, value)
                    else:
                        result[i] = (key, value)
                    break
            else:
                result.append((key, value))
    return result

