def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, str):
        return (seq, str)
    elif isinstance(seq, bytes):
        return (seq, bytes)
    elif isinstance(seq, bytearray):
        return (seq, bytearray)
    elif isinstance(seq, memoryview):
        return (seq, memoryview)
    elif isinstance(seq, array.array):
        return (seq, array.array)
    elif isinstance(seq, collections.abc.Sequence):
        return (seq, collections.abc.Sequence)
    else:
        raise TypeError("Expected a sequence type, but got %s" % type(seq))

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if tentative:
        # If the candidate is tentative, we only need to check that it
        # has the necessary methods and attributes, without actually
        # calling them.
        for method in iface.methods:
            if not hasattr(candidate, method.name):
                return False
        for attribute in iface.attributes:
            if not hasattr(candidate, attribute.name):
                return False
        return True
    else:
        # If the candidate is not tentative, we need to actually call
        # the methods and check that they return the correct values.
        for method in iface.methods:
            if not method.verify(candidate):
                return False
        for attribute in iface.attributes:
            if not attribute.verify(candidate):
                return False
        return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    for base in bases:
        if hasattr(base, "__metaclass__"):
            return base.__metaclass__
    return type(bases[0])

def pop(self, key, default=None):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not None:
            return default
        raise KeyError(key)
    for map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap,
                self._pb.BoolMap]:
        if key in map.keys():
            return map.pop(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    try:
        node = self._head[2]
        if node is self._tail:
            raise KeyError('list is empty')
        self._find_lt(node[0])
        self._remove(node)
        return (node[0], node[1])
    except KeyError, e:
        raise BadRequestKeyError(str(e))

def popitem(self):
    """Remove and return the (key, value) pair least recently used.

    This method raises a KeyError if the list is empty.
    """
    node = self._head[2]
    if node is self._tail:
        raise KeyError('list is empty')
    self._find_lt(node[0])
    self._remove(node)
    return (node[0], node[1])

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used.

    This method raises a `KeyError` if the dict is empty.
    """
    try:
        key, value = next(reversed(self.items()))
        del self[key]
        return key, value
    except StopIteration:
        raise KeyError("dict is empty")

def popitem(self):
    """Remove and return a random (key, value) pair."""
    if not self:
        raise KeyError("list is empty")
    key = random.choice(list(self.keys()))
    value = self.pop(key)
    return (key, value)

