def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    new_text = ''
    in_code_block = False
    for line in text.splitlines():
        if not in_code_block:
            for tag in line.split():
                if tag.startswith('#'):
                    tags.add(tag[1:])
                    if replacer is not None:
                        new_text += replacer(tag[1:]) + ' '
                    else:
                        new_text += tag + ' '
        else:
            new_text += line + '\n'
        if line.startswith('```'):
            in_code_block = not in_code_block
    return tags, new_text

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.

    :param url: The URL of the remote resource.
    :return: The content type of the remote resource, or None if the content type could not be determined.
    """

    try:
        response = requests.head(url)
        if response.status_code == 200:
            return response.headers.get('content-type')
        else:
            return None
    except requests.exceptions.RequestException:
        return None

def xml_children_as_dict(node):
    """
    Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    children = node.getchildren()
    result = {}
    for child in children:
        tag = child.tag
        if tag not in result:
            result[tag] = []
        result[tag].append(child.text)
    return result

