def validate_from_content(spec_content):
    """
    Validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """

    # Load the spec content into a dictionary
    spec_data = yaml.load(spec_content, Loader=yaml.FullLoader)

    # Check if the spec data has all required fields
    for field in cls.REQUIRED_FIELDS:
        if field not in spec_data:
            raise IRValidatorException(f"Mandatory field '{field}' is missing in spec file")

    # Check if the spec data has all required fields with the correct types
    for field, field_type in cls.REQUIRED_FIELDS_TYPES.items():
        if field not in spec_data or not isinstance(spec_data[field], field_type):
            raise IRValidatorException(f"Field '{field}' in spec file has incorrect type, expected {field_type}")

    # Check if the spec data has all required fields with the correct values
    for field, field_values in cls.REQUIRED_FIELDS_VALUES.items():
        if field not in spec_data or spec_data[field] not in field_values:
            raise IRValidatorException(f"Field '{field}' in spec file has incorrect value, expected one of {field_values}")

    return spec_data

def validate_from_file(yaml_file):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    with open(yaml_file, 'r') as f:
        data = yaml.load(f)

    # Check if all mandatory fields are present
    for field in cls.mandatory_fields:
        if field not in data:
            raise IRValidatorException(f"Mandatory field '{field}' is missing in the YAML file")

    # Check if all fields have the correct type
    for field, field_type in cls.field_types.items():
        if field not in data:
            continue
        if not isinstance(data[field], field_type):
            raise IRValidatorException(f"Field '{field}' has incorrect type. Expected {field_type}, got {type(data[field])}")

    return data

def _include_groups(self, parser_dict):
    """
    Resolves the include dict directive in the spec files.

    :param dict parser_dict:
    """
    for key, value in parser_dict.items():
        if isinstance(value, dict):
            self._include_groups(value)
        elif key == 'include':
            include_file = value
            with open(include_file, 'r') as f:
                include_dict = json.load(f)
            parser_dict.update(include_dict)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary of default values for the arguments.
    """
    defaults = {}
    for arg in self.args:
        # Check if the argument has a default value set in the spec
        if arg.default is not None:
            defaults[arg.name] = arg.default
        # Check if the argument has a default value set in the other sources
        if arg.default_source is not None:
            defaults[arg.name] = arg.default_source
    return defaults

