    }

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Get the list of deprecated arguments
    deprecated_args = self.parsed_yaml.get('deprecated_args', [])

    # Check if any of the arguments in the cli_args are deprecated
    for arg in cli_args:
        if arg in deprecated_args:
            print(f"Warning: The argument '{arg}' is deprecated and will be removed in a future version. Please use '{deprecated_args[arg]}' instead.")

    # Check if any of the arguments in the answer_file_args are deprecated
    for arg in answer_file_args:
        if arg in deprecated_args:
            print(f"Warning: The argument '{arg}' is deprecated and will be removed in a future version. Please use '{deprecated_args[arg]}' instead.")

    # Check if any of the arguments in the cli_args or answer_file_args are deprecated
    for arg in cli_args.keys() | answer_file_args.keys():
        if arg in deprecated_args:
            print(f"Warning: The argument '{arg}' is deprecated and will be removed in a future version. Please use '{deprecated_args[arg]}' instead.")

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(arg) > self.length:
            raise ValueError(f"Argument {arg} is longer than {self.length}")

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if arg_name in self.choices:
            if arg_value not in self.choices[arg_name]:
                raise ValueError(f"Invalid value for argument {arg_name}: {arg_value}. Must be one of {self.choices[arg_name]}")
        else:
            raise ValueError(f"Invalid argument: {arg_name}. Must be one of {self.choices.keys()}")

def validate_min_max_args(args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if arg < 0 or arg > 100:
            raise ValueError("Argument value must be between 0 and 100")
    return args

def get_nested_custom_and_control_args(args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """

    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('--'):
            if arg in CONTROL_ARGS:
                control_args[arg] = args[arg]
            elif arg in NESTED_ARGS:
                nested_args[arg] = args[arg]
            elif arg in CUSTOM_ARGS:
                custom_args[arg] = args[arg]

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict
    else:
        for var in extra_vars:
            if var not in vars_dict:
                vars_dict[var] = None
        return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = {}
    with open(os.path.join(plugin_dir, "plugin.json")) as f:
        plugin_spec = json.load(f)
    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flatten_dict[f"{key}.{subkey}"] = subvalue
        else:
            flatten_dict[key] = value
    return flatten_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        os.environ['CONFIG_PATH'] = self.config_path
